// Symbols inside are local to the translation unit (internal linkage)

namespace {
    // Compiler generates a unique, mangled name for 'data'
    // (e.g., __anon_1_data)
    int data = 10;

    void local_init() {
        data = 1;
    }

    class PrivateUtility {
        // Only accessible within this TU
        int value;
    };
}

// data, local_init, and PrivateUtility are inaccessible
// and invisible outside this specific source file.
